package com.clinora.admin.bootstrap;import com.clinora.audit.AuthAuditAction;import com.clinora.audit.AuthAuditOutcome;import com.clinora.audit.AuthAuditService;import com.clinora.config.SystemAdminProperties;import com.clinora.security.PasswordService;import com.clinora.users.domain.UserAccount;import com.clinora.users.repository.UserAccountRepository;import com.clinora.users.service.EmailAddressNormalizer;import java.time.Clock;import java.time.Instant;import java.util.Optional;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Isolation;import org.springframework.transaction.annotation.Transactional;@Component@Profile("dev")public class SystemAdminDevelopmentSeeder implements ApplicationRunner {    private static final Logger LOGGER = LoggerFactory.getLogger(SystemAdminDevelopmentSeeder.class);    private final UserAccountRepository users;    private final PasswordService passwords;    private final AuthAuditService audit;    private final Clock clock;    private final SystemAdminProperties properties;    private final EmailAddressNormalizer emailNormalizer;    private final String devPassword;    public SystemAdminDevelopmentSeeder(        UserAccountRepository users,        PasswordService passwords,        AuthAuditService audit,        Clock clock,        SystemAdminProperties properties,        EmailAddressNormalizer emailNormalizer,        @Value("${clinora.dev.admin.password:}") String devPassword    ) {        this.users = users;        this.passwords = passwords;        this.audit = audit;        this.clock = clock;        this.properties = properties;        this.emailNormalizer = emailNormalizer;        this.devPassword = devPassword == null ? "" : devPassword;    }    @Override    @Transactional(isolation = Isolation.SERIALIZABLE)    public void run(ApplicationArguments args) {        if (devPassword.isBlank()) {            return;        }        String email = properties.getEmail();        if (email == null || email.isBlank()) {            return;        }        String normalizedEmail = emailNormalizer.normalize(email);        Optional<UserAccount> adminOpt = users.findByNormalizedEmail(normalizedEmail);        if (adminOpt.isEmpty()) {            LOGGER.info("No System Admin found to reset in dev mode.");            return;        }        UserAccount admin = adminOpt.get();        Instant now = clock.instant();        String newHash = passwords.hash(devPassword);        admin.changePasswordHash(newHash, now);        UserAccount saved = users.save(admin);        audit.record(            null,            AuthAuditAction.SYSTEM_ADMIN_BOOTSTRAPPED,            AuthAuditOutcome.SUCCESS,            null,            null,            saved.getId().toString(),            "source=dev-admin-reset"        );        LOGGER.info("System Admin password was reset using CLINORA_DEV_ADMIN_PASSWORD.");    }}